#!/bin/bash
# Emobile — установка сайта с редактированием по паролю на Ubuntu.
# Запуск:  sudo bash servis-setup.sh
set -e
DOMAIN="servismaster.duckdns.org"   # домен сайта (пусто — без домена и https)
AUTO=0; NEWPASS=0; for a in "$@"; do case "$a" in --auto) AUTO=1;; --password) NEWPASS=1;; --domain=*) DOMAIN="${a#--domain=}";; esac; done
[ "$(id -u)" = 0 ] || { echo "Запустите от root"; exit 1; }
echo "== Устанавливаю nginx и python3 =="
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq
apt-get install -y -qq nginx python3 curl >/dev/null
[ -n "$DOMAIN" ] && apt-get install -y -qq certbot python3-certbot-nginx >/dev/null

echo "== Копирую файлы сайта =="
id servis >/dev/null 2>&1 || useradd --system --no-create-home --shell /usr/sbin/nologin servis
install -d -m 755 /opt/servis-master /var/www/html
install -d -m 755 -o servis -g servis /var/lib/servis-master
install -d -m 750 -o root -g servis /etc/servis-master
cat > /opt/servis-master/server.py <<'PYEOF'
#!/usr/bin/env python3
"""Emobile — маленький сервер для сохранения прайса.

POST /api/login   {"password": "..."}      -> {"token": "..."}
PUT  /api/prices  (Authorization: Bearer T) -> сохраняет прайс в prices.json
POST /api/logout  (Authorization: Bearer T)

Только стандартная библиотека Python 3. Статику отдаёт nginx.
Смена пароля:  python3 server.py --set-password
"""
import argparse, getpass, hashlib, hmac, json, os, secrets, shutil, sys, threading, time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

DATA = os.environ.get('SERVIS_DATA', '/var/lib/servis-master')
AUTH_FILE = os.environ.get('SERVIS_AUTH', '/etc/servis-master/auth.json')
TOKEN_DAYS = 30
MAX_BODY = 5 * 1024 * 1024
lock = threading.Lock()
fails = {}  # ip -> [count, until]


def load_json(path, default):
    try:
        with open(path, encoding='utf-8') as f:
            return json.load(f)
    except Exception:
        return default


def write_atomic(path, text, mode=0o644):
    tmp = path + '.tmp'
    with open(tmp, 'w', encoding='utf-8') as f:
        f.write(text)
    os.chmod(tmp, mode)
    os.replace(tmp, path)


def hash_pw(pw, salt):
    return hashlib.pbkdf2_hmac('sha256', pw.encode('utf-8'), bytes.fromhex(salt), 200_000).hex()


def set_password():
    pw = getpass.getpass('Новый пароль для редактирования сайта: ')
    if len(pw) < 4:
        sys.exit('Пароль слишком короткий (минимум 4 символа).')
    if pw != getpass.getpass('Повторите пароль: '):
        sys.exit('Пароли не совпадают.')
    salt = secrets.token_hex(16)
    os.makedirs(os.path.dirname(AUTH_FILE), exist_ok=True)
    write_atomic(AUTH_FILE, json.dumps({'salt': salt, 'hash': hash_pw(pw, salt)}), 0o600)
    tokens = os.path.join(DATA, 'tokens.json')
    if os.path.exists(tokens):
        os.remove(tokens)  # выйти со всех устройств
    print('Пароль сохранён.')


def check_pw(pw):
    a = load_json(AUTH_FILE, None)
    if not a:
        return False
    return hmac.compare_digest(hash_pw(pw, a['salt']), a['hash'])


def tokens_path():
    return os.path.join(DATA, 'tokens.json')


def valid_token(tok):
    if not tok:
        return False
    now = time.time()
    with lock:
        toks = {k: v for k, v in load_json(tokens_path(), {}).items() if v > now}
    return any(hmac.compare_digest(tok, k) for k in toks)


def valid_prices(d):
    if not isinstance(d, dict) or not isinstance(d.get('brands'), list) or not isinstance(d.get('models'), list):
        return False
    for b in d['brands']:
        if not isinstance(b, dict) or not isinstance(b.get('id'), str) or not isinstance(b.get('name'), str):
            return False
    for m in d['models']:
        if not isinstance(m, dict) or not isinstance(m.get('name'), str) or not isinstance(m.get('services', []), list):
            return False
        for s in m.get('services', []):
            if not isinstance(s, dict) or not isinstance(s.get('name', ''), str):
                return False
            try:
                float(s.get('price', 0))
            except (TypeError, ValueError):
                return False
    return True


class H(BaseHTTPRequestHandler):
    server_version = 'ServisMaster/1.0'

    def log_message(self, fmt, *args):
        sys.stderr.write('%s %s\n' % (self.ip(), fmt % args))

    def ip(self):
        return self.headers.get('X-Real-IP') or self.client_address[0]

    def send(self, code, obj):
        body = json.dumps(obj, ensure_ascii=False).encode('utf-8')
        self.send_response(code)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def body(self):
        n = int(self.headers.get('Content-Length') or 0)
        if n <= 0 or n > MAX_BODY:
            return None
        try:
            return json.loads(self.rfile.read(n).decode('utf-8'))
        except Exception:
            return None

    def token(self):
        h = self.headers.get('Authorization', '')
        return h[7:].strip() if h.startswith('Bearer ') else ''

    def do_POST(self):
        if self.path == '/api/login':
            ip = self.ip()
            c, until = fails.get(ip, [0, 0])
            if until > time.time():
                return self.send(429, {'error': 'wait'})
            d = self.body() or {}
            if check_pw(str(d.get('password', ''))):
                fails.pop(ip, None)
                tok = secrets.token_urlsafe(32)
                with lock:
                    now = time.time()
                    toks = {k: v for k, v in load_json(tokens_path(), {}).items() if v > now}
                    toks[tok] = now + TOKEN_DAYS * 86400
                    write_atomic(tokens_path(), json.dumps(toks), 0o600)
                return self.send(200, {'token': tok})
            time.sleep(1)
            c += 1
            fails[ip] = [c, time.time() + 300 if c >= 5 else 0]
            if c >= 5:
                fails[ip][0] = 0
            return self.send(401, {'error': 'bad password'})
        if self.path == '/api/logout':
            tok = self.token()
            with lock:
                toks = load_json(tokens_path(), {})
                toks.pop(tok, None)
                write_atomic(tokens_path(), json.dumps(toks), 0o600)
            return self.send(200, {'ok': True})
        if self.path == '/api/check':
            return self.send(200 if valid_token(self.token()) else 401, {})
        self.send(404, {'error': 'not found'})

    def do_PUT(self):
        if self.path != '/api/prices':
            return self.send(404, {'error': 'not found'})
        if not valid_token(self.token()):
            return self.send(401, {'error': 'login required'})
        d = self.body()
        if not valid_prices(d):
            return self.send(400, {'error': 'bad data'})
        path = os.path.join(DATA, 'prices.json')
        with lock:
            if os.path.exists(path):  # резервная копия, храним последние 100
                bdir = os.path.join(DATA, 'backups')
                os.makedirs(bdir, exist_ok=True)
                shutil.copy2(path, os.path.join(bdir, time.strftime('prices-%Y%m%d-%H%M%S.json')))
                old = sorted(os.listdir(bdir))[:-100]
                for f in old:
                    os.remove(os.path.join(bdir, f))
            write_atomic(path, json.dumps(d, ensure_ascii=False))
        self.send(200, {'ok': True})

    # Только для локальной проверки: --static DIR отдаёт файлы сайта
    def do_GET(self):
        st = getattr(self.server, 'static', None)
        if not st:
            return self.send(404, {'error': 'not found'})
        p = self.path.split('?')[0]
        f = os.path.join(DATA, 'prices.json') if p == '/prices.json' else os.path.join(st, (p.strip('/') or 'index.html'))
        if not os.path.isfile(f):
            return self.send(404, {'error': 'not found'})
        data = open(f, 'rb').read()
        self.send_response(200)
        self.send_header('Content-Type', 'application/json' if f.endswith('.json') else 'text/html; charset=utf-8')
        self.send_header('Content-Length', str(len(data)))
        self.end_headers()
        self.wfile.write(data)


if __name__ == '__main__':
    ap = argparse.ArgumentParser()
    ap.add_argument('--set-password', action='store_true')
    ap.add_argument('--port', type=int, default=8787)
    ap.add_argument('--host', default='127.0.0.1')
    ap.add_argument('--static')
    a = ap.parse_args()
    if a.set_password:
        set_password()
        sys.exit(0)
    os.makedirs(DATA, exist_ok=True)
    srv = ThreadingHTTPServer((a.host, a.port), H)
    srv.static = a.static
    print('Emobile API на %s:%d' % (a.host, a.port), flush=True)
    srv.serve_forever()
PYEOF
echo "" | base64 -d > /var/www/html/index.html
chmod 644 /var/www/html/index.html /opt/servis-master/server.py

if [ "$AUTO" = 0 ] && { [ ! -f /etc/servis-master/auth.json ] || [ "$NEWPASS" = 1 ]; }; then
  echo "== Придумайте пароль для редактирования сайта =="
  until python3 /opt/servis-master/server.py --set-password; do echo "Попробуйте ещё раз."; done
fi
[ -f /etc/servis-master/auth.json ] && { chown servis:servis /etc/servis-master/auth.json; chmod 600 /etc/servis-master/auth.json; }
if [ "$AUTO" = 0 ]; then rm -f /var/lib/servis-master/tokens.json; fi

cat > /usr/local/bin/servis-password <<'SH'
#!/bin/bash
python3 /opt/servis-master/server.py --set-password && chown servis:servis /etc/servis-master/auth.json /var/lib/servis-master/tokens.json 2>/dev/null; systemctl restart servis-master
SH
chmod 755 /usr/local/bin/servis-password

# Автообновление: раз в 5 минут сервер проверяет GitHub и, если вышла новая версия, ставит её сам.
# Работает, только если репозиторий публичный. Цены и пароль не трогает.
if [ -f "$0" ]; then cp "$0" /opt/servis-master/installed.sh 2>/dev/null || true; fi
cat > /usr/local/bin/servis-update <<'SH'
#!/bin/bash
URL="https://raw.githubusercontent.com/milanodprsd/site-for-emobile/main/servis-setup.sh"
exec 9>/run/servis-update.lock; flock -n 9 || exit 0
TMP=$(mktemp) || exit 1
trap 'rm -f "$TMP"' EXIT
curl -fsSL --max-time 60 "$URL" -o "$TMP" || exit 0
grep -q "Emobile" "$TMP" && bash -n "$TMP" || exit 0
cmp -s "$TMP" /opt/servis-master/installed.sh && exit 0
echo "Найдена новая версия сайта, обновляю..."
bash "$TMP" --auto && cp "$TMP" /opt/servis-master/installed.sh
SH
chmod 755 /usr/local/bin/servis-update
cat > /etc/systemd/system/servis-update.service <<'UNIT'
[Unit]
Description=Servis Master auto-update from GitHub
[Service]
Type=oneshot
ExecStart=/usr/local/bin/servis-update
UNIT
cat > /etc/systemd/system/servis-update.timer <<'UNIT'
[Unit]
Description=Check GitHub for site updates every 5 minutes
[Timer]
OnBootSec=2min
OnUnitActiveSec=5min
[Install]
WantedBy=timers.target
UNIT

cat > /etc/systemd/system/servis-master.service <<'UNIT'
[Unit]
Description=Servis Master price API
After=network.target
[Service]
User=servis
ExecStart=/usr/bin/python3 /opt/servis-master/server.py
Restart=always
NoNewPrivileges=true
ProtectSystem=full
[Install]
WantedBy=multi-user.target
UNIT

cat > /etc/nginx/sites-available/servis-master <<'NGX'
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name __SERVER_NAME__;
    root /var/www/html;
    index index.html;
    client_max_body_size 5m;
    location = /prices.json {
        alias /var/lib/servis-master/prices.json;
        add_header Cache-Control "no-store";
    }
    location /api/ {
        proxy_pass http://127.0.0.1:8787;
        proxy_set_header X-Real-IP $remote_addr;
    }
    location / {
        try_files $uri $uri/ =404;
        add_header Cache-Control "no-cache";
    }
}
NGX
sed -i "s/__SERVER_NAME__/${DOMAIN:-_}/" /etc/nginx/sites-available/servis-master
rm -f /etc/nginx/sites-enabled/default
ln -sf /etc/nginx/sites-available/servis-master /etc/nginx/sites-enabled/servis-master

echo "== Запускаю =="
systemctl daemon-reload
systemctl enable --now servis-master >/dev/null 2>&1
systemctl restart servis-master
systemctl enable --now servis-update.timer >/dev/null 2>&1 || true
nginx -t -q && systemctl enable nginx >/dev/null 2>&1 && systemctl restart nginx
if command -v ufw >/dev/null; then ufw allow 80/tcp >/dev/null; ufw allow 443/tcp >/dev/null; ufw allow OpenSSH >/dev/null 2>&1 || true; fi
iptables -C INPUT -p tcp --dport 80 -j ACCEPT 2>/dev/null || iptables -I INPUT -p tcp --dport 80 -j ACCEPT 2>/dev/null || true

HTTPS=0
if [ -n "$DOMAIN" ]; then
  echo "== Включаю https для $DOMAIN =="
  if certbot --nginx -d "$DOMAIN" --non-interactive --agree-tos --register-unsafely-without-email --redirect --keep-until-expiring -q; then
    HTTPS=1
  else
    echo "!! https пока не включился (проверьте, что домен указывает на этот сервер). Сайт работает по http."
  fi
fi

sleep 1
IP=$(curl -s -4 --max-time 5 ifconfig.me || hostname -I | awk '{print $1}')
if curl -s -o /dev/null -w '%{http_code}' -H "Host: ${DOMAIN:-localhost}" http://127.0.0.1/ | grep -qE '200|301' && systemctl is-active -q servis-master; then
  echo ""
  if [ "$HTTPS" = 1 ]; then echo "ГОТОВО! Сайт: https://$DOMAIN"; elif [ -n "$DOMAIN" ]; then echo "ГОТОВО! Сайт: http://$DOMAIN  (или http://$IP)"; else echo "ГОТОВО! Сайт: http://$IP"; fi
  echo "Чтобы редактировать: нажмите на замок в шапке сайта и введите пароль."
  echo "Сменить пароль: servis-password"
else
  echo "Что-то пошло не так:"; systemctl --no-pager status nginx servis-master | tail -20
fi
